-- Semillas de productos y categorias desde practica03/backups/olaf.sql.
-- Cargar en db_test con un usuario autorizado; el usuario real quedara en tb_logs.
-- No reemplaza datos existentes: productos se comparan por SKU y categorias por nombre.
-- Revise el resultado y haga COMMIT o ROLLBACK manualmente en la MISMA sesion.
-- Solo para las tablas de db_test del respaldo db_test_2026-11-11_133613.sql.
USE db_test;
SET NAMES utf8mb4;

DROP TEMPORARY TABLE IF EXISTS semilla_productos, semilla_categorias, semilla_relaciones, semilla_categorias_nuevas;
CREATE TEMPORARY TABLE semilla_productos (origen_id INT UNSIGNED PRIMARY KEY, SKU VARCHAR(50) NOT NULL, nombre VARCHAR(250) NOT NULL, descripcion TEXT, precio DECIMAL(10,2) NOT NULL, stock INT UNSIGNED NOT NULL, estado BIT(1) NOT NULL, creado DATETIME NOT NULL, actualizado DATETIME NOT NULL);
CREATE TEMPORARY TABLE semilla_categorias (origen_id INT UNSIGNED PRIMARY KEY, nombre VARCHAR(120) NOT NULL, descripcion TEXT, padre_id INT UNSIGNED, estado BIT(1) NOT NULL, creado DATETIME NOT NULL, actualizado DATETIME NOT NULL);
CREATE TEMPORARY TABLE semilla_relaciones (categoria_id INT UNSIGNED NOT NULL, producto_id INT UNSIGNED NOT NULL, estado BIT(1) NOT NULL, creado DATETIME NOT NULL, actualizado DATETIME NOT NULL, PRIMARY KEY(categoria_id, producto_id));

