-- Conteos de origen y coincidencias previas.
SELECT (SELECT COUNT(*) FROM semilla_productos) AS productos_origen, (SELECT COUNT(*) FROM tb_products) AS productos_actuales, (SELECT COUNT(*) FROM semilla_productos s JOIN tb_products p ON p.SKU=s.SKU) AS sku_existentes;
SELECT (SELECT COUNT(*) FROM semilla_categorias) AS categorias_origen, (SELECT COUNT(*) FROM tbc_categories) AS categorias_actuales, (SELECT COUNT(*) FROM semilla_categorias s JOIN tbc_categories c ON c.name=s.nombre) AS categorias_existentes;
SELECT COUNT(*) AS relaciones_origen FROM semilla_relaciones;

-- Las tablas temporales se preparan antes de iniciar la transaccion.
CREATE TEMPORARY TABLE semilla_categorias_nuevas (origen_id INT UNSIGNED PRIMARY KEY);
INSERT INTO semilla_categorias_nuevas SELECT s.origen_id FROM semilla_categorias s LEFT JOIN tbc_categories c ON c.name=s.nombre WHERE c.ID IS NULL;
START TRANSACTION;

INSERT INTO tbc_categories (name, description, sup_id_category, status, creation_date, last_update)
SELECT s.nombre, s.descripcion, NULL, s.estado, s.creado, s.actualizado FROM semilla_categorias s JOIN semilla_categorias_nuevas n ON n.origen_id=s.origen_id;
-- Solo se asigna la categoria superior a categorias recien insertadas.
UPDATE tbc_categories c JOIN semilla_categorias s ON s.nombre=c.name JOIN semilla_categorias_nuevas n ON n.origen_id=s.origen_id JOIN semilla_categorias padre ON padre.origen_id=s.padre_id JOIN tbc_categories destino_padre ON destino_padre.name=padre.nombre SET c.sup_id_category=destino_padre.ID;

INSERT INTO tb_products (SKU, name, description, current_price, current_stock, status, creation_date, last_update)
SELECT s.SKU, s.nombre, s.descripcion, s.precio, s.stock, CAST(s.estado AS UNSIGNED), s.creado, s.actualizado FROM semilla_productos s LEFT JOIN tb_products p ON p.SKU=s.SKU WHERE p.ID IS NULL;

INSERT INTO tbd_products_categories (product_ID, category_ID, status, creation_date, last_update)
SELECT p.ID, c.ID, r.estado, r.creado, r.actualizado FROM semilla_relaciones r JOIN semilla_productos sp ON sp.origen_id=r.producto_id JOIN tb_products p ON p.SKU=sp.SKU JOIN semilla_categorias sc ON sc.origen_id=r.categoria_id JOIN tbc_categories c ON c.name=sc.nombre LEFT JOIN tbd_products_categories actual ON actual.product_ID=p.ID AND actual.category_ID=c.ID WHERE actual.ID IS NULL;

SELECT (SELECT COUNT(*) FROM tb_products) AS productos_final, (SELECT COUNT(*) FROM tbc_categories) AS categorias_final, (SELECT COUNT(*) FROM tbd_products_categories) AS relaciones_final;
